"""Testes da aplicação (Sala 101 única) no Chromium com viewport de celular, contra o emulador do Node-RED em outra origem."""
import re, sys
from playwright.sync_api import sync_playwright
from _helpers import *

HAS_T = "!!CampusSmart.core.store.get().telemetry"
def new_page(b, w=375, h=720):
    pg = b.new_context(viewport={'width': w, 'height': h}, is_mobile=True, has_touch=True).new_page(); pg.errors = []
    pg.on('pageerror', lambda e: pg.errors.append(str(e))); return pg
def open_(pg, hash_='#/inicio', q=''):
    pg.goto(f'{WEB}/index.html{q}{hash_}'); pg.wait_for_function(HAS_T, timeout=8000)
def go(pg, hash_, sel=None):
    pg.evaluate(f"location.hash={hash_!r}")
    if sel: pg.wait_for_selector(sel)
def close_modal(pg): pg.evaluate('CampusSmart.ui.modal.close()')
def wait_modal(pg, t, timeout=8000): pg.wait_for_selector(f'#modal .modal[data-type={t}]', timeout=timeout)
def fetch_now(pg): pg.evaluate('CampusSmart.core.telemetry.fetchOnce()'); pg.wait_for_timeout(400)
def tog(equip, turn): return f'[data-action=toggle][data-equip={equip}][data-turn={turn}]'
def confirm(pg, turn_on): pg.click('#modalActions .btn.primary' if turn_on else '#modalActions .btn.danger')
def badge(pg, eq): return pg.inner_text(f'[data-equip-card={eq}] .state-badge')
def H1(pg): return pg.inner_text('#view h1')
def sel_alerts(pg): return pg.evaluate("CampusSmart.core.selectors.alerts(CampusSmart.core.store.get()).length")

with sync_playwright() as p, Env():
    b = p.chromium.launch()

    # ------------------------------------------------------------------ 1-3: Dashboard e telemetria
    print('\n[1-3] Dashboard da Sala 101, telemetria e atualização dos dados')
    reset(); pg = new_page(b); open_(pg); pg.wait_for_selector('#dbEquip .equipment')
    check('identificação "Sala 101"', pg.inner_text('#dbName') == 'Sala 101')
    check('status de ocupação (Vazia)', pg.inner_text('#dbOcc') == 'Vazia')
    check('temperatura, umidade, potência e energia exibidas', all(pg.inner_text(i) != '—' for i in ('#mTemp', '#mHum', '#mPower', '#mEnergy')))
    check('dois indicadores SEPARADOS: "Potência atual" e "Consumo acumulado"', 'Potência atual' in pg.inner_text('#cardPower') and 'Consumo acumulado' in pg.inner_text('#cardEnergy') and pg.locator('#cardPower #mEnergy').count() == 0)
    tel = pg.evaluate("CampusSmart.core.store.get().telemetry"); shown = pg.inner_text('#cardPower b')
    check('potência atual em kW quando ≥ 1000 W (ex.: 1,55 kW) com o valor em W logo abaixo', tel['potencia'] >= 1000 and 'kW' in shown and ' W' in pg.inner_text('#mPowerNote'), shown + ' | ' + pg.inner_text('#mPowerNote'))
    raw = pg.evaluate("CampusSmart.lastRawTelemetry")
    check('valor exibido = valor real da telemetria (sem número fixo): potência', abs(float(pg.inner_text('#mPower').replace(',', '.')) - raw['potencia_w'] / 1000) < 0.006)
    check('valor exibido = valor real da telemetria: consumo acumulado em kWh', abs(float(pg.inner_text('#mEnergy').replace(',', '.')) - raw['energia_kwh']) < 0.0006 and pg.inner_text('#cardEnergy b').strip().endswith('kWh'))
    check('Dashboard mostra só o ar-condicionado, com estado "Ligado"', pg.locator('#dbEquip .equipment').count() == 1 and 'Ar-condicionado' in pg.inner_text('#dbEquip') and 'Ligado' in pg.inner_text('#dbEquip'))
    check('nenhuma menção à iluminação no Dashboard', not re.search(r'ilumina|luz', pg.inner_text('#view'), re.I))
    check('mini-gráfico de consumo (potência) aparece após 2 leituras', (fetch_now(pg) or True) and pg.locator('.spark-card:not([hidden])').count() == 1)
    check('alerta de desperdício no dashboard (sala vazia + ar-condicionado ligado)', pg.locator('#dbAlerts .recent-row').count() == 1 and 'ALTA' in pg.inner_text('#dbAlerts') and 'Ar-condicionado' in pg.inner_text('#dbAlerts'))
    check('selo de alertas no menu', pg.inner_text('#navAlertCount') == '1')
    check('conexão com o Node-RED: Online', pg.inner_text('#connText') == 'Online')
    n0 = pg.evaluate("CampusSmart.core.store.get().history.length"); fetch_now(pg); fetch_now(pg)
    check('telemetria atualiza (novas leituras chegam)', pg.evaluate("CampusSmart.core.store.get().history.length") >= n0 + 1)
    check('hora da última atualização exibida', re.search(r'Atualizado \d\d:\d\d:\d\d', pg.inner_text('#lastUpdate')) is not None)
    emu('inject/cs_inj_occ'); fetch_now(pg)
    check('ocupação muda para "Ocupada" quando o Node-RED informa', pg.inner_text('#dbOcc') == 'Ocupada')
    check('sala ocupada: nenhum alerta e mensagem de ausência', 'Nenhum desperdício identificado' in pg.inner_text('#dbAlerts') and pg.locator('#navAlertCount:visible').count() == 0)
    emu('inject/cs_inj_occ'); fetch_now(pg); check('sala vazia de novo: alerta volta', pg.locator('#dbAlerts .recent-row').count() == 1)

    # ------------------------------------------------------------------ 4-5, 8: AC
    print('\n[4-5, 8] Ar-condicionado: desligar e ligar (POST reais) e atualização do estado')
    go(pg, '#/controle', '[data-equip-card=ac]')
    check('Controle mostra só o ar-condicionado (nenhum outro equipamento)', pg.locator('[data-equip-card]').count() == 1 and not re.search(r'ilumina|luz', pg.inner_text('#view'), re.I))
    check('estado do AC claramente indicado (Ligado) e botão "Desligar ar-condicionado"', badge(pg, 'ac') == 'Ligado' and 'Desligar ar-condicionado' in pg.inner_text(tog('ac', 'off')))
    pg.click(tog('ac', 'off'))
    check('confirmação com a pergunta e botões Cancelar / Desligar', pg.inner_text('#modalTitle') == 'Tem certeza que deseja desligar este equipamento?' and pg.inner_text('#modalActions').split() == ['Cancelar', 'Desligar'])
    pg.click('#modalActions .btn:first-child'); check('Cancelar não envia comando', emu('stats')['state']['ac'] is True)
    pg.click(tog('ac', 'off')); confirm(pg, False); wait_modal(pg, 'success')
    check('sucesso exibido após o Node-RED confirmar', 'Equipamento desligado' in pg.inner_text('#modalTitle') and emu('stats')['state']['ac'] is False)
    pg.wait_for_selector(tog('ac', 'on'), timeout=8000); close_modal(pg)
    check('estado do AC atualizado para "Desligado" e botão vira "Ligar ar-condicionado"', badge(pg, 'ac') == 'Desligado' and 'Ligar ar-condicionado' in pg.inner_text(tog('ac', 'on')))
    check('POST ac/cut enviado como formulário (sem preflight)', [r for r in emu('stats')['requests'] if r['path'] == '/api/v1/rooms/101/ac/cut'][-1]['contentType'].startswith('application/x-www-form-urlencoded'))
    go(pg, '#/inicio', '[data-equip-row=ac]'); check('Dashboard reflete: ar-condicionado "Desligado"', pg.inner_text('[data-equip-row=ac] .state-badge') == 'Desligado')
    check('com o AC desligado o alerta de desperdício some', pg.locator('#dbAlerts .recent-row').count() == 0 and 'Nenhum desperdício identificado' in pg.inner_text('#dbAlerts'))
    go(pg, '#/controle', '[data-equip-card=ac]'); pg.click(tog('ac', 'on'))
    check('confirmação para ligar com botões Cancelar / Ligar', pg.inner_text('#modalTitle') == 'Tem certeza que deseja ligar este equipamento?' and pg.inner_text('#modalActions').split() == ['Cancelar', 'Ligar'])
    pg.click('#modalActions .btn:first-child'); check('Cancelar não liga', emu('stats')['state']['ac'] is False)
    pg.click(tog('ac', 'on')); confirm(pg, True); wait_modal(pg, 'success')
    check('LIGAR o ar-condicionado: sucesso e Node-RED com AC ligado', 'Equipamento ligado' in pg.inner_text('#modalTitle') and emu('stats')['state']['ac'] is True)
    pg.wait_for_selector(tog('ac', 'off'), timeout=8000); close_modal(pg)
    check('estado do AC volta a "Ligado"', badge(pg, 'ac') == 'Ligado')
    go(pg, '#/inicio', '#mPower'); pg.wait_for_function("CampusSmart.core.store.get().telemetry.potencia>1000", timeout=8000)
    check('telemetria atualizada após ligar (potência volta a subir)', True)

    go(pg, '#/controle', '[data-equip-card=ac]')

    # ------------------------------------------------------------------ 7: modo automático / carga + OLED
    print('\n[7] Modo da carga (ON / OFF / AUTO) e display OLED')
    def tel(): return pg.evaluate("CampusSmart.core.store.get().telemetry")
    def send_mode(cmd):
        pg.click(f'[data-action=load][data-cmd={cmd}]'); wait_modal(pg, 'success'); close_modal(pg)
        pg.wait_for_function(f"document.querySelector('[data-cmd={cmd}]').getAttribute('aria-pressed')==='true'", timeout=8000)
    emu('inject/cs_inj_occ') if emu('stats')['state']['ocupada'] else None; fetch_now(pg)          # garante sala VAZIA
    send_mode('ON'); fetch_now(pg)
    check('ON: Node-RED recebeu e a tela mostra modo ON', emu('stats')['state']['modo'] == 'ON' and pg.inner_text('#loadMode') == 'ON')
    check('ON: telemetria informa carga energizada e potência alta (> 1000 W)', tel()['cargaLigada'] is True and tel()['potencia'] > 1000 and pg.inner_text('#loadState') == 'energizada')
    send_mode('OFF'); fetch_now(pg)
    check('OFF: Node-RED recebeu e a tela mostra modo OFF', emu('stats')['state']['modo'] == 'OFF' and pg.inner_text('#loadMode') == 'OFF')
    check('OFF: telemetria informa carga CORTADA e a potência cai (< 500 W)', tel()['cargaLigada'] is False and tel()['potencia'] < 500 and pg.inner_text('#loadState') == 'cortada')
    check('OFF: ar-condicionado aparece "Sem alimentação" e não gera alerta de desperdício', badge(pg, 'ac') == 'Sem alimentação' and sel_alerts(pg) == 0)
    go(pg, '#/inicio', '#dbLoad'); check('Dashboard: carga cortada · modo OFF, potência em W e AC "Sem alimentação"', 'cortada' in pg.inner_text('#dbLoad') and 'OFF' in pg.inner_text('#dbLoad') and pg.inner_text('#mPowerUnit') == 'W' and pg.inner_text('[data-equip-row=ac] .state-badge') == 'Sem alimentação')
    go(pg, '#/controle', '#loadControl')
    send_mode('AUTO'); fetch_now(pg)
    check('AUTO com sala vazia: Node-RED recebeu e a carga fica cortada', emu('stats')['state']['modo'] == 'AUTO' and pg.inner_text('#loadMode') == 'AUTO' and tel()['cargaLigada'] is False and tel()['potencia'] < 500)
    emu('inject/cs_inj_occ'); fetch_now(pg)
    check('AUTO com sala OCUPADA: carga energizada e potência sobe', tel()['cargaLigada'] is True and tel()['potencia'] > 1000 and pg.inner_text('#loadState') == 'energizada' and badge(pg, 'ac') == 'Ligado')
    emu('inject/cs_inj_occ'); fetch_now(pg)
    check('AUTO: sala esvazia → a carga é cortada de novo (lógica automática)', tel()['cargaLigada'] is False and pg.inner_text('#loadState') == 'cortada')
    send_mode('ON'); fetch_now(pg)
    check('voltar para ON restaura a carga e o alerta de desperdício (sala vazia)', tel()['cargaLigada'] is True and sel_alerts(pg) == 1)
    pg.click('[data-action=load][data-cmd=OFF]'); wait_modal(pg, 'success')
    check('modal de sucesso do comando de carga descreve o efeito', 'carga desligada' in pg.inner_text('#modalText')); close_modal(pg)
    check('histórico de comandos recebe "Modo da carga: OFF"', any(c['label'] == 'Modo da carga: OFF' and c['status'] == 'sucesso' for c in pg.evaluate("CampusSmart.services.history.get().commands")))
    sent = emu('stats')['requests']; loads = [r for r in sent if r['path'] == '/api/v1/comando-carga']
    check('botões enviam POST /api/v1/comando-carga com ON, OFF e AUTO (formulário, sem preflight)', len(loads) >= 5 and all(r['method'] == 'POST' and r['contentType'].startswith('application/x-www-form-urlencoded') for r in loads))
    check('nenhum OPTIONS (preflight) foi disparado pelo front-end', not [r for r in sent if r['method'] == 'OPTIONS'])
    print('\n[OLED] Mensagem ao display')
    check('enviar desabilitado com campo vazio', pg.is_disabled('#oledSend'))
    pg.fill('#oledText', '    '); check('enviar desabilitado com campo só de espaços', pg.is_disabled('#oledSend'))
    pg.fill('#oledText', 'Atenção: desligue o ar & feche'); check('contador de caracteres', pg.inner_text('#oledCount') == '30')
    pg.click('#oledSend'); wait_modal(pg, 'success')
    check('sucesso só após 2xx e o texto diz o que foi confirmado (recebido pelo Node-RED, sem afirmar exibição física)', 'servidor confirmou o recebimento' in pg.inner_text('#modalText') and 'enviada ao ESP32' in pg.inner_text('#modalText'), pg.inner_text('#modalText'))
    close_modal(pg)
    check('mensagem recebida pelo Node-RED com acentos e símbolos, e campo limpo', emu('stats')['state']['oled'] == 'Atenção: desligue o ar & feche' and pg.input_value('#oledText') == '')
    r = [x for x in emu('stats')['requests'] if x['path'] == '/api/v1/mensagem'][-1]
    check('POST /api/v1/mensagem como formulário (campo "mensagem"), sem preflight', r['method'] == 'POST' and r['contentType'].startswith('application/x-www-form-urlencoded'))
    check('histórico registra a mensagem com sucesso', any(c['label'] == 'Mensagem ao display OLED' and c['status'] == 'sucesso' for c in pg.evaluate("CampusSmart.services.history.get().commands")))
    pg.fill('#oledText', 'x' * 100); check('limite de 64 caracteres no campo', len(pg.input_value('#oledText')) == 64 and pg.inner_text('#oledCount') == '64'); pg.fill('#oledText', '')
    pg.evaluate("CampusSmart.core.actions.sendOled('y'.repeat(65))"); wait_modal(pg, 'error')
    check('validação antes do envio: 65 caracteres → "Mensagem inválida" e nada é enviado', pg.inner_text('#modalTitle') == 'Mensagem inválida' and '64' in pg.inner_text('#modalText') and len([x for x in emu('stats')['requests'] if x['path'] == '/api/v1/mensagem']) == 1)
    check('erro de validação oferece só "Fechar" (repetir não resolveria)', pg.inner_text('#modalActions').split() == ['Fechar']); close_modal(pg)
    pg.evaluate("CampusSmart.ui.modal.runCommand({loadingText:'t', request:()=>CampusSmart.services.http.request(CampusSmart.endpoints.comandoCarga,{method:'POST',body:{comando:'XYZ'}}), successTitle:'x', successText:'x'})")
    wait_modal(pg, 'error')
    check('erro 400 do servidor mostra o código e o motivo devolvido pelo Node-RED', 'código 400' in pg.inner_text('#modalText') and 'comando inválido' in pg.inner_text('#modalText'), pg.inner_text('#modalText')); close_modal(pg)
    check('sem erros de JavaScript', not pg.errors, '; '.join(pg.errors)); pg.close()

    # ------------------------------------------------------------------ potência e consumo: robustez
    print('\n[2b] Potência atual e consumo acumulado com outros formatos de telemetria')
    pg = new_page(b); open_(pg, '#/inicio', '?mock=altnames'); pg.wait_for_selector('#mPower')
    check('potência em kW e energia em Wh (objeto "consumo") são convertidas para W/kW e kWh', pg.inner_text('#mPower') != '—' and pg.inner_text('#mEnergy') != '—' and pg.inner_text('#cardEnergy b').strip().endswith('kWh'))
    t = pg.evaluate("CampusSmart.core.store.get().telemetry"); r = pg.evaluate("CampusSmart.lastRawTelemetry")
    check('conversões corretas (kW→W e Wh→kWh)', abs(t['potencia'] - r['consumo']['potencia_kw'] * 1000) < 0.01 and abs(t['energia'] - r['consumo']['energia_wh'] / 1000) < 0.0001); pg.close()
    pg = new_page(b); open_(pg, '#/inicio', '?mock=nopower'); pg.wait_for_selector('#mPower')
    check('sem potência/energia na telemetria: "Não informado pela telemetria" (nenhum número inventado)', pg.inner_text('#mPower') == '—' and pg.inner_text('#mEnergy') == '—' and pg.inner_text('#mPowerNote') == 'Não informado pela telemetria' and pg.inner_text('#mEnergyNote') == 'Não informado pela telemetria')
    check('e o restante do dashboard continua funcionando', pg.inner_text('#dbOcc') == 'Vazia' and pg.locator('#dbEquip .equipment').count() == 1); pg.close()
    pg = new_page(b); open_(pg); n1 = pg.evaluate("CampusSmart.core.store.get().telemetry.energia"); pg.wait_for_timeout(300); fetch_now(pg); fetch_now(pg)
    n2 = pg.evaluate("CampusSmart.core.store.get().telemetry.energia")
    check('consumo acumulado só cresce com o tempo (nunca diminui nem salta)', n2 >= n1 and (n2 - n1) < 0.05, f'{n1} -> {n2}')
    check('atualização automática: intervalo de 5 s configurado em config.js', pg.evaluate("CampusSmart.config.POLL_MS") == 5000)
    n0 = pg.evaluate("CampusSmart.core.store.get().history.length"); pg.wait_for_function(f"CampusSmart.core.store.get().history.length > {n0}", timeout=9000)
    check('atualização automática: nova leitura chega sozinha, sem clique (polling)', True); pg.close()

    # ------------------------------------------------------------------ 9: erros
    print('\n[9] Erros de comunicação (sem simular sucesso)')
    reset(); pg = new_page(b); open_(pg, '#/controle'); pg.wait_for_selector(tog('ac', 'off')); emu('inject/cs_inj_off')
    pg.click(tog('ac', 'off')); confirm(pg, False); wait_modal(pg, 'error')
    check('503 → "Dispositivo offline" com Fechar e Tentar novamente', pg.inner_text('#modalTitle') == 'Dispositivo offline' and pg.inner_text('#modalActions').split('\n') == ['Fechar', 'Tentar novamente'])
    pg.click('#modalActions .btn:first-child'); check('AC continua ligado no Node-RED (nenhum falso sucesso)', emu('stats')['state']['ac'] is True)
    pg.click(tog('ac', 'off')); confirm(pg, False); wait_modal(pg, 'error'); emu('inject/cs_inj_off')
    pg.click('#modalActions .btn.primary'); wait_modal(pg, 'success'); check('Tentar novamente reenvia e conclui (AC desligado)', emu('stats')['state']['ac'] is False)
    close_modal(pg); emu('inject/cs_inj_off'); pg.wait_for_selector(tog('ac', 'on'), timeout=8000)
    pg.click(tog('ac', 'on')); confirm(pg, True); wait_modal(pg, 'error'); check('erro também ao LIGAR com dispositivo offline', pg.inner_text('#modalTitle') == 'Dispositivo offline' and emu('stats')['state']['ac'] is False)
    pg.click('#modalActions .btn:first-child'); fetch_now(pg)    # Node-RED continua offline: o indicador deve refletir
    check('indicador de conexão mostra "Dispositivo offline" quando o Node-RED responde 503', pg.get_attribute('#connPill', 'data-state') == 'offline' and pg.inner_text('#connText') == 'Dispositivo offline')
    emu('inject/cs_inj_off'); fetch_now(pg); check('e volta a "Online" quando o dispositivo retorna', pg.inner_text('#connText') == 'Online'); pg.close()
    reset(); pg = new_page(b); open_(pg, '#/controle', '?mock=cmdnet'); pg.click(tog('ac', 'off')); confirm(pg, False); wait_modal(pg, 'error')
    check('falha de rede → "Sem conexão"', pg.inner_text('#modalTitle') == 'Sem conexão'); pg.close()
    pg = new_page(b); open_(pg, '#/controle', '?mock=503'); pg.fill('#oledText', 'oi'); pg.click('#oledSend'); wait_modal(pg, 'error')
    check('OLED com 503 → "Dispositivo offline"', pg.inner_text('#modalTitle') == 'Dispositivo offline'); pg.close()
    pg = new_page(b); open_(pg, '#/controle', '?mock=cmdnet'); pg.fill('#oledText', 'oi'); pg.click('#oledSend'); wait_modal(pg, 'error')
    check('OLED sem rede → "Sem conexão" com "Tentar novamente" (nenhum falso sucesso)', pg.inner_text('#modalTitle') == 'Sem conexão' and 'Tentar novamente' in pg.inner_text('#modalActions')); pg.close()
    pg = new_page(b); open_(pg, '#/controle', '?mock=1')
    check('modo simulação identificado na tela (faixa "SIMULAÇÃO")', 'SIMULAÇÃO' in pg.inner_text('#mockBanner'))
    pg.fill('#oledText', 'teste'); pg.click('#oledSend'); wait_modal(pg, 'success')
    check('OLED em simulação: sucesso diz explicitamente que é SIMULAÇÃO e que nada chegou ao display', pg.inner_text('#modalText').startswith('SIMULAÇÃO') and 'display' in pg.inner_text('#modalText')); pg.close()
    pg = new_page(b); open_(pg, '#/controle'); check('sem ?mock não existe faixa de simulação', pg.locator('#mockBanner').count() == 0); pg.close()
    pg = new_page(b); open_(pg, '#/controle', '?mock=slow'); pg.click(tog('ac', 'off')); confirm(pg, False); wait_modal(pg, 'loading', 2000)
    check('carregamento enquanto aguarda (sem sucesso antecipado)', pg.locator('#modal .modal[data-type=success]').count() == 0)
    pg.keyboard.press('Escape'); check('carregamento não fecha com Esc', pg.locator('#modal.show').count() == 1)
    wait_modal(pg, 'success', 6000); check('sucesso só depois da resposta', True); pg.close()

    # ------------------------------------------------------------------ 10: estados
    print('\n[10] Estados: carregando, vazio, sem comunicação, controle indisponível')
    reset(); pg = new_page(b); pg.goto(f'{WEB}/index.html?mock=1#/inicio'); pg.wait_for_selector('.state-box .spinner', timeout=3000)
    check('carregamento: "Carregando dados da Sala 101…"', 'Carregando dados da Sala 101' in pg.inner_text('#view')); pg.wait_for_function(HAS_T); pg.close()
    pg = new_page(b); pg.goto(f'{WEB}/index.html?mock=down#/inicio'); pg.wait_for_selector('.state-box.error', timeout=6000)
    check('erro inicial: "Sem comunicação com o Node-RED" + Tentar novamente', 'Sem comunicação com o Node-RED' in pg.inner_text('#view') and pg.locator('[data-action=retry-telemetry]').count() == 1)
    check('indicador de conexão mostra falha', pg.get_attribute('#connPill', 'data-state') == 'offline')
    for h in ('#/controle', '#/alertas'):
        go(pg, h); pg.wait_for_selector('.state-box.error'); check(f'{h}: mesmo estado de erro (não afirma "sem alertas")', 'Nenhum desperdício' not in pg.inner_text('#view'))
    pg.close()
    reset(); pg = new_page(b); open_(pg, '#/alertas', ''); emu('inject/cs_inj_occ'); fetch_now(pg)
    check('Alertas: mensagem quando não há desperdícios', 'Nenhum desperdício identificado' in pg.inner_text('#view') and pg.locator('.alert-card').count() == 0)
    emu('inject/cs_inj_off'); fetch_now(pg)
    check('Alertas com Node-RED fora: aviso de dados desatualizados', 'Sem comunicação com o Node-RED' in pg.inner_text('#view') and 'desatualizados' in pg.inner_text('#view')); emu('inject/cs_inj_off'); emu('inject/cs_inj_occ'); pg.close()
    pg = new_page(b); open_(pg, '#/controle', '?mock=noac')
    check('AC não informado pela telemetria: estado "Não informado" e SEM botão de controle', badge(pg, 'ac') == 'Não informado' and pg.locator('[data-equip-card=ac] button').count() == 0)
    check('modo da carga e OLED continuam disponíveis', pg.locator('[data-action=load]').count() == 3 and pg.locator('#oledText').count() == 1)
    go(pg, '#/inicio', '[data-equip-row=ac]'); check('Dashboard: AC "Não informado" (nada inventado)', pg.inner_text('[data-equip-row=ac] .state-badge') == 'Não informado'); pg.close()

    print('\n[10b] Regras de alerta (função pura)')
    pg = new_page(b); open_(pg)
    r = pg.evaluate("""(()=>{const A=CampusSmart.core.alerts, room=CampusSmart.data.roomProfile, base={ocupada:false,acLigado:true,potencia:1000};
      const ids=t=>A.deriveAlerts(room,Object.assign({},base,t)).map(a=>a.id+':'+a.level);
      return {vazia:ids({}), ocupada:ids({ocupada:true}), acOff:ids({acLigado:false}), pico:ids({ocupada:true,potencia:2500}), semTel:A.deriveAlerts(room,null).length}})()""")
    check('sala vazia + AC ligado → alerta de prioridade alta', r['vazia'] == ['ac-vazia:high'])
    check('sala ocupada → sem alertas', r['ocupada'] == []); check('AC desligado → sem alertas', r['acOff'] == [])
    check('potência acima do limite → alerta de prioridade baixa', r['pico'] == ['consumo-alto:low']); check('sem telemetria → nenhum alerta inventado', r['semTel'] == 0); pg.close()

    # ------------------------------------------------------------------ Histórico
    print('\n[Histórico] Estrutura preparada, sem inventar dados')
    reset(); pg = new_page(b); open_(pg, '#/historico'); pg.wait_for_selector('#histNote')
    check('aviso: registros só desta sessão; histórico completo virá do back-end/banco', 'Registros desta sessão' in pg.inner_text('#histNote') and 'banco de dados' in pg.inner_text('#histNote'))
    check('comandos: mensagem de vazio (nada inventado)', 'Nenhum comando enviado nesta sessão' in pg.inner_text('#histCommands'))
    check('estados: mensagem de vazio', 'Nenhuma alteração de estado registrada' in pg.inner_text('#histStates'))
    fetch_now(pg); fetch_now(pg)
    check('consumo: leituras reais com horário, potência e energia', pg.locator('#histConsumption .hist-row:not(.head)').count() >= 2 and re.search(r'\d\d:\d\d:\d\d', pg.inner_text('#histConsumption')) is not None)
    go(pg, '#/controle', tog('ac', 'off')); pg.click(tog('ac', 'off')); confirm(pg, False); wait_modal(pg, 'success'); close_modal(pg); pg.wait_for_selector(tog('ac', 'on'), timeout=8000)
    emu('inject/cs_inj_off'); pg.click(tog('ac', 'on')); confirm(pg, True); wait_modal(pg, 'error'); close_modal(pg); emu('inject/cs_inj_off')
    go(pg, '#/historico', '#histCommands'); cmds = pg.inner_text('#histCommands')
    check('comandos enviados com horário e resultado (sucesso e erro)', 'Desligar ar-condicionado' in cmds and 'Sucesso' in cmds and 'Ligar ar-condicionado' in cmds and 'Erro' in cmds and re.search(r'\d\d:\d\d:\d\d', cmds) is not None)
    check('histórico sem menção à iluminação', not re.search(r'ilumina|luz', pg.inner_text('#view'), re.I))
    check('alteração de estado registrada (Ar-condicionado: Ligado → Desligado)', 'Ar-condicionado: Ligado → Desligado' in pg.inner_text('#histStates'))
    pg.close()
    pg = new_page(b); pg.goto(f'{WEB}/index.html?mock=down#/historico'); pg.wait_for_selector('#histNote')
    check('sem telemetria o histórico continua acessível e vazio (sem dados inventados)', 'Ainda não há leituras de consumo' in pg.inner_text('#histConsumption')); pg.close()

    # ------------------------------------------------------------------ 11, 14: navegação e Sala única
    print('\n[11, 14] Navegação entre as telas e ausência de outras salas')
    reset(); pg = new_page(b); open_(pg, '')
    OTHER = re.compile(r'Sala (?!101)\d+|Salas|Lista de salas|Auditório|Biblioteca|Lab\.|Ociosas')
    for nav, h1 in [('inicio', 'Sala 101'), ('controle', 'Controle da sala'), ('alertas', 'Alertas'), ('historico', 'Histórico')]:
        pg.click(f'.nav-item[data-nav={nav}]'); pg.wait_for_function(f"document.querySelector('#view h1') && document.querySelector('#view h1').textContent==={h1!r}")
        check(f'menu → {h1}', pg.get_attribute(f'.nav-item[data-nav={nav}]', 'aria-current') == 'page')
        check(f'{h1}: nenhuma informação de outras salas', not OTHER.search(pg.inner_text('#view') + pg.inner_text('.bottom-nav')))
        check(f'{h1}: sem busca, filtro ou seleção de ambiente', pg.locator('#view input[type=search], #view select, #view [role=search], #view [data-room]').count() == 0)
    for old in ('#/salas', '#/salas/102', '#/fluxo'):
        go(pg, old); pg.wait_for_selector('#dbName'); check(f'rota antiga {old} cai no Dashboard da Sala 101', pg.inner_text('#dbName') == 'Sala 101')
    go(pg, '#/alertas', '.alert-card'); card = pg.inner_text('.alert-card')
    check('Alertas: equipamento, motivo, tipo, prioridade e estado', all(x in card for x in ('Equipamento:', 'Tipo de desperdício:', 'Prioridade: Alta', 'Estado: Ativo')) and 'Sala vazia com o ar-condicionado ligado' in card)
    pg.click('.alert-card >> text=Ir para o controle'); pg.wait_for_selector('[data-equip-card=ac]'); check('Alertas → "Ir para o controle"', H1(pg) == 'Controle da sala')
    pg.go_back(); pg.wait_for_selector('.alert-card'); check('botão Voltar do navegador funciona', H1(pg) == 'Alertas')
    check('sem erros de JavaScript na navegação', not pg.errors, '; '.join(pg.errors)); pg.close()

    # ------------------------------------------------------------------ 12: responsividade
    print('\n[12] Responsividade em celulares')
    for dev, (w, h) in {'iPhone SE 375x667': (375, 667), 'Galaxy S8 360x740': (360, 740), 'iPhone 14 Pro Max 430x932': (430, 932), 'tela mínima 320x568': (320, 568)}.items():
        reset(); pg = new_page(b, w, h); open_(pg, '#/inicio'); problems = []
        for route in ('#/inicio', '#/controle', '#/alertas', '#/historico'):
            go(pg, route); pg.wait_for_timeout(250)
            if not pg.evaluate("document.documentElement.scrollWidth <= innerWidth"): problems.append(f'{route}: rolagem horizontal')
            small = pg.evaluate("""[...document.querySelectorAll('a,button,textarea')].filter(e=>{const r=e.getBoundingClientRect();return r.width>0&&r.height>0&&r.height<43.5}).map(e=>(e.textContent||e.id).trim().slice(0,20))""")
            if small: problems.append(f'{route}: alvos pequenos {small}')
        check(f'{dev}: sem rolagem horizontal e alvos de toque ≥ 44px em todas as telas', not problems, '; '.join(problems))
        if w == 375: go(pg, '#/controle', '#oledText'); check('campo de texto ≥ 16px (sem zoom no iOS)', pg.evaluate("parseFloat(getComputedStyle(document.querySelector('#oledText')).fontSize)>=16"))
        pg.close()
    print('\n[12b] Responsividade em tablet e computador')
    for dev, (w, h) in {'tablet 768x1024': (768, 1024), 'notebook 1366x768': (1366, 768), 'monitor 1920x1080': (1920, 1080)}.items():
        reset(); pg = b.new_context(viewport={'width': w, 'height': h}).new_page(); pg.errors = []; pg.on('pageerror', lambda e: pg.errors.append(str(e)))
        pg.goto(f'{WEB}/index.html#/inicio'); pg.wait_for_function(HAS_T, timeout=8000); problems = []
        for route in ('#/inicio', '#/controle', '#/alertas', '#/historico'):
            go(pg, route); pg.wait_for_timeout(200)
            if not pg.evaluate("document.documentElement.scrollWidth <= innerWidth"): problems.append(f'{route}: rolagem horizontal')
        box = pg.evaluate("(()=>{const r=document.querySelector('.phone').getBoundingClientRect();return {w:r.width,l:r.left,r:innerWidth-r.right}})()")
        check(f'{dev}: sem rolagem horizontal, coluna de até 430 px centralizada', not problems and box['w'] <= 430.5 and abs(box['l'] - box['r']) < 2, f"{problems} {box}")
        go(pg, '#/inicio'); check(f'{dev}: indicadores de potência e consumo lado a lado e legíveis', pg.evaluate("(()=>{const a=document.querySelector('#cardPower').getBoundingClientRect(),c=document.querySelector('#cardEnergy').getBoundingClientRect();return Math.abs(a.top-c.top)<2&&a.right<=c.left+10})()"))
        pg.close()
    b.close()
sys.exit(summary())
